import React, { useState, useEffect, useRef } from "react";
import { MapContainer, TileLayer, GeoJSON } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import Slider from "react-slider";
import "./App.css";
import { useMapEvents } from "react-leaflet";

function ZoomWatcher({ onZoomChange }) {
  useMapEvents({
    zoomend: (e) => {
      const newZoom = e.target.getZoom();
      onZoomChange(newZoom);
    },
  });
  return null;
}

const presidentTurnoutThresholds = [
  { limit: 50, color: "#e6f4ea" },
  { limit: 60, color: "#a6d9b7" },
  { limit: 65, color: "#5bbf83" },
  { limit: 70, color: "#3a9d66" },
  { limit: 101, color: "#21814f" },
];

const mayorTurnoutThresholds = [
  { limit: 40, color: "#e6f4ea" },
  { limit: 50, color: "#a6d9b7" },
  { limit: 60, color: "#5bbf83" },
  { limit: 70, color: "#3a9d66" },
  { limit: 101, color: "#21814f" },
];

function getStyleByDataType(props, dataType, year, activeElectionLevel) {
  const mode =
    year === 2012 && activeElectionLevel === "Президент"
      ? "2012_president_"
      : "2013_mer_";

  if (dataType === "Явка") {
    const value = props[`${mode}явка`] || 0;

    const threshold =
      year === 2012 && activeElectionLevel === "Президент"
        ? presidentTurnoutThresholds
        : mayorTurnoutThresholds;

    const color =
      threshold.find((t) => value < t.limit)?.color || "#ccc";

    return {
      color: "#000",
      weight: 1,
      fillOpacity: 0.8,
      fillColor: color,
    };
  }

  if (dataType === "Процент испорченных бюллетеней") {
    const value = props[`${mode}недействительных`] || 0;
    const color =
      invalidThresholds.find((t) => value < t.limit)?.color || "#ccc";
    return {
      color: "#000",
      weight: 1,
      fillOpacity: 0.8,
      fillColor: color,
    };
  }
}

function App() {
  const [year, setYear] = useState(2012);
  const [geoData, setGeoData] = useState(null);
  const [activeDataType, setActiveDataType] = useState("Победитель");
  const [activeElectionLevel, setActiveElectionLevel] = useState("Госдума");
  const [activeListType, setActiveListType] = useState("Округ");
  const [mapZoom, setMapZoom] = useState(10);
  const [districtData, setDistrictData] = useState(null);
  const [uikData, setUikData] = useState(null);
  const [legendLevels, setLegendLevels] = useState({});
  const [districtLegendLevels, setDistrictLegendLevels] = useState({});
  const [selectedFeature, setSelectedFeature] = useState(null);
  const mapRef = useRef();

  useEffect(() => {
    if (year === 2012 && activeElectionLevel === "Президент") {
      fetch("/data/moscow_2012_president_results.geojson")
        .then((res) => res.json())
        .then((data) => {
          console.log("Loaded 2012 data:", data);
          setDistrictData(data);
        });
    } else if (year === 2013 && activeElectionLevel === "Мэр") {
      fetch("/data/districts_with_2013_mer.geojson")
        .then((res) => res.json())
        .then((data) => {
          console.log("Loaded 2013 Mer data:", data);
          setDistrictData(data);
          const levels = getAdvantageLevels(data.features);
          setDistrictLegendLevels(levels);
        });

      fetch("/data/united_uiks_with_final_2013_mer.geojson")
        .then((res) => res.json())
        .then((data) => {
          console.log("Loaded 2013 Uik data:", data);
          setUikData(data);
        });
    }
  }, [year, activeElectionLevel]);

  const showDistrictLayer = (year === 2013 && activeElectionLevel === "Мэр") || (year === 2012 && activeElectionLevel === "Президент");
  const showPrecinctLayer = showDistrictLayer && mapZoom > 13;

  return (
    <div className="App">
      <div className="title-wrapper">
        <div className="title-decorated">
          <h1>Выборы Москвы</h1>
        </div>
      </div>

      <div className="slider-container">
        <label>Год: {year}</label>
        <Slider
          className="slider"
          value={year}
          min={2012}
          max={2022}
          step={1}
          onChange={setYear}
          renderTrack={(props) => <div {...props} className="slider-track" />}
          renderThumb={(props) => <div {...props} className="slider-thumb" />}
        />
      </div>

      <div className="map-wrapper">
        <div className="map-container">
          <div className="top-controls">
            {["Явка", "Победитель", "Процент испорченных бюллетеней"].map((label) => (
              <button
                key={label}
                className={activeDataType === label ? "active" : ""}
                onClick={() => setActiveDataType(label)}
              >
                {label}
              </button>
            ))}
          </div>

          {activeElectionLevel === "Госдума" && (
            <div className="center-controls">
              {["Округ", "Список"].map((label) => (
                <button
                  key={label}
                  className={activeListType === label ? "active" : ""}
                  onClick={() => setActiveListType(label)}
                >
                  {label}
                </button>
              ))}
            </div>
          )}

          <div className="controls">
            {["Госдума", "Мосгордума", "Муниципальные", "Мэр", "Президент"].map((label) => (
              <button
                key={label}
                className={activeElectionLevel === label ? "active" : ""}
                onClick={() => setActiveElectionLevel(label)}
              >
                {label}
              </button>
            ))}
          </div>

          <MapContainer
            center={[55.7558, 37.6173]}
            zoom={10}
            className="map-container"
            whenCreated={(map) => {
              mapRef.current = map;
              map.on("zoomend", () => setMapZoom(map.getZoom()));
            }}
          >
            {showDistrictLayer && districtData && !showPrecinctLayer && (
              <GeoJSON
                data={districtData}
                style={(feature) => {
                  if (activeDataType === "Победитель") {
                    return {
                      color: "#000",
                      weight: 2,
                      fillOpacity: 1,
                      fillColor: getWinnerColorByAdvantage(feature.properties),
                    };
                  }
                  return getStyleByDataType(feature.properties, activeDataType, year, activeElectionLevel);
                }}
                onEachFeature={(feature, layer) => {
                  layer.on({
                    click: () => {
                      setSelectedFeature(feature);
                    },
                  });
                }}
              />
            )}

            {showPrecinctLayer && uikData && (
              <GeoJSON
                data={uikData}
                style={(feature) => {
                  if (activeDataType === "Победитель") {
                    return {
                      color: "#333",
                      weight: 1,
                      fillOpacity: 1,
                      fillColor: getWinnerColorByAdvantage(feature.properties),
                    };
                  }
                  return getStyleByDataType(feature.properties, activeDataType, year, activeElectionLevel);
                }}
                onEachFeature={(feature, layer) => {
                  layer.on({
                    click: () => {
                      setSelectedFeature(feature);
                    },
                  });
                }}
              />
            )}

            {selectedFeature && (
              <GeoJSON
                data={{
                  type: "FeatureCollection",
                  features: [selectedFeature],
                }}
                style={{
                  color: "#ff7800",
                  weight: 3,
                  fillOpacity: 0.2,
                  dashArray: "5, 5",
                }}
              />
            )}
          </MapContainer>
        </div>
      </div>
    </div>
  );
}

export default App;
